What is the output of the following C++ code?

#include <iostream>
struct A {
    virtual void show() { std::cout << "A"; }
};
struct B : A {
    void show() { std::cout << "B"; }
};
int main() {
    B b;
    A a = b;
    a.show();
    return 0;
}

What is the output of the following C++ code?

#include <iostream>
int main() {
    int x = 5;
    auto f = [x]() mutable { x += 10; return x; };
    f();
    std::cout << x;
    return 0;
}
